  // A layer id: a plain one above, or 'crops:<crop>', 'minerals:<mineral>', 'historic:<period>'.
  function layerDef(lid) {
    if (typeof lid !== 'string') return null;
    if (LAYERS[lid]) return LAYERS[lid];
    const [a, b] = lid.split(':');
    if (a === 'crops' && CROPS[b]) return { n: CROPS[b].n, in: true, crop: b, items: () => CROPS[b].st.map((c) => BYCODE[c]) };
    if (a === 'minerals' && MINERALS[b]) return { n: MINERALS[b].n, in: true, mineral: b, items: () => MINERALS[b].s.slice() };
    if (a === 'historic' && PERIODS[b]) return { n: PERIODS[b].n, in: true, period: b, items: () => PERIODS[b].s.slice() };
    return null;
  }
  const LAYER_LIST = Object.keys(LAYERS).concat(Object.keys(CROPS).map((c) => 'crops:' + c), Object.keys(MINERALS).map((m) => 'minerals:' + m), Object.keys(PERIODS).map((p) => 'historic:' + p));

